def find_closest_elements(numbers: List[float]) -> Tuple[float, float]:
    sorted_nums = sorted(numbers)
    n = len(sorted_nums)

    # Find all adjacent pairs with distinct values
    candidates = []
    for i in range(n - 1):
        a, b = sorted_nums[i], sorted_nums[i + 1]
        if a != b:
            candidates.append((b - a, a, b))

    if not candidates:
        # All values are the same
        return (sorted_nums[0], sorted_nums[1])

    min_diff = min(c[0] for c in candidates)

    # Among candidates with min_diff, pick the one with average closest to median
    median = (sorted_nums[n // 2] if n % 2 == 1 
              else (sorted_nums[n // 2 - 1] + sorted_nums[n // 2]) / 2)

    best = None
    best_dist = float('inf')
    for diff, a, b in candidates:
        if diff == min_diff:
            avg = (a + b) / 2
            dist_to_median = abs(avg - median)
            if dist_to_median < best_dist:
                best_dist = dist_to_median
                best = (a, b)

    return best

