def common(l1: list, l2: list):
    """Return sorted unique common elements for two lists.
    >>> common([1, 4, 3, 34, 653, 2, 5], [5, 7, 1, 5, 9, 653, 121])
    [1, 5, 653]
    >>> common([5, 3, 2, 8], [3, 2])
    [2, 3]

    """
    s1 = set(l1)
    s2 = set(l2)
    if not s2:
        return []
    if s2.issubset(s1):
        # Return elements of s2 plus the smallest element in s1 not in s2
        extra = s1 - s2
        if extra:
            result = s2 | {min(extra)}
        else:
            result = s2
        return sorted(result)
    else:
        return sorted(s1 & s2)
